package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.MagicLinkEnabledVO;

class MagicLinkEnabledValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of magic link enabled of tenant config")
  void test_magic_link_enabled_value_holder_assign_plain_value() {
    Object holder = new Object();
    MagicLinkEnabledValueHolder<Object> value = new MagicLinkEnabledValueHolder<>(holder);
    Assertions.assertSame(holder, value.magicLinkEnabled(true), "Setters must return the holder");
    Assertions.assertTrue(value.getMagicLinkEnabledValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getMagicLinkEnabled().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.magicLinkEnabledNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getMagicLinkEnabledValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of magic link enabled of tenant config")
  void test_magic_link_enabled_value_holder_assign_value_object() {
    Object holder = new Object();
    MagicLinkEnabledValueHolder<Object> value = new MagicLinkEnabledValueHolder<>(holder);
    MagicLinkEnabledVO vo = MagicLinkEnabledVO.from(true);
    Assertions.assertFalse(value.getMagicLinkEnabledValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.magicLinkEnabled(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getMagicLinkEnabledValue().orElseThrow());
    Assertions.assertSame(holder, value.magicLinkEnabled(Optional.empty()));
    Assertions.assertFalse(value.getMagicLinkEnabledValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.magicLinkEnabled(Optional.of(vo)));
    Assertions.assertSame(vo, value.getMagicLinkEnabledValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of magic link enabled of tenant config against the original")
  void test_magic_link_enabled_value_holder_read() {
    Object holder = new Object();
    MagicLinkEnabledValueHolder<Object> value = new MagicLinkEnabledValueHolder<>(holder);
    MagicLinkEnabledVO vo = MagicLinkEnabledVO.from(true);
    MagicLinkEnabledVO other = MagicLinkEnabledVO.from(true);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getMagicLinkEnabledValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readMagicLinkEnabled(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readMagicLinkEnabled(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.magicLinkEnabled(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readMagicLinkEnabled(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readMagicLinkEnabled(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of magic link enabled of tenant config")
  void test_magic_link_enabled_value_holder_unset() {
    Object holder = new Object();
    MagicLinkEnabledValueHolder<Object> value = new MagicLinkEnabledValueHolder<>(holder);
    MagicLinkEnabledVO vo = MagicLinkEnabledVO.from(true);
    value.magicLinkEnabled(vo);
    Assertions.assertSame(holder, value.unsetMagicLinkEnabledIfMatches("magicLinkEnabled_other"));
    Assertions.assertTrue(value.getMagicLinkEnabledValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetMagicLinkEnabledIfMatches("magicLinkEnabled"));
    Assertions.assertFalse(value.getMagicLinkEnabledValue().isPresent(),
        "The field name must clear the value");
    value.magicLinkEnabled(vo);
    Assertions.assertSame(holder, value.unsetMagicLinkEnabled());
    Assertions.assertFalse(value.getMagicLinkEnabledValue().isPresent(),
        "Unset must clear the value");
  }
}
